insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('edlohn', 'edlohn', 'Webbasierte Lohnabrechnung für Kanzleien und Lohnbüros', 'Webbasierte Lohnabrechnung der eurodata AG, verbreitet bei Lohnbüros, Kanzleien und Mittelständlern.', '<p>edlohn ist die webbasierte Lohnabrechnung der eurodata AG aus Saarbrücken. Sie wird vor allem von Lohnbüros und Steuerkanzleien genutzt, eignet sich aber auch für Unternehmen mit eigener Lohnbuchhaltung.</p><p>Die Abrechnung läuft vollständig im Browser; das Hosting erfolgt im eurodata-Rechenzentrum in Deutschland.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), null, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, 'Abrechnung über die Steuerkanzlei', '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","bAV & Entgeltumwandlung","Umlagen U1/U2/U3","Mitarbeiterportal","DATEV-Schnittstelle","Baulohn"]'::jsonb, '["Webbasiert, keine Installation","Rechenzentrum in Deutschland","Baulohn-Fähigkeit"]'::jsonb, '["DATEV","eurodata edtime"]'::jsonb, '["Keine Installation","Gute Alternative zu DATEV"]'::jsonb, '["Weniger bekannt bei Unternehmen","Preis nur auf Anfrage"]'::jsonb, 'Lohnbüros, Kanzleien und Mittelständler mit eigener Lohnbuchhaltung.', null, 'ja', 'export', '[]'::jsonb, true, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.eurodata.de/edlohn', 'keins', 'eurodata AG', null, 'Saarbrücken', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.1, 3.9, 4, 4.1, 4.4, 'edlohn von eurodata ist eine webbasierte Lohnabrechnung, die sich vor allem an Steuerkanzleien und ihre Mandanten richtet. Für Betriebe mit Filialen und Stundenlöhnen, etwa in Gastronomie und Handel, ist es besonders interessant.', '<h3>Einordnung</h3><p>eurodata aus Saarbrücken ist seit Jahrzehnten Rechenzentrumsdienstleister für Kanzleien. edlohn ist die Lohnlösung dieses Ökosystems und läuft vollständig im Browser. Kanzlei und Mandant arbeiten auf denselben Daten, was die Vorerfassung von Stunden und Zuschlägen einfach macht.</p><h3>Stärken</h3><p>Stark ist edlohn bei Branchen mit vielen Stundenkräften und wechselnden Einsätzen. Die Anbindung an Kassen- und Zeiterfassungssysteme, wie sie in Gastronomie und Handel verbreitet sind, spart manuelle Übertragungen.</p><h3>Kosten und Fazit</h3><p>Die Abrechnung erfolgt in der Regel über die Kanzlei, öffentliche Endkundenpreise gibt es nicht. Wenn Ihre Kanzlei mit eurodata arbeitet, ist edlohn eine sehr gute Wahl. Sonst lohnt sich ein Gespräch über die Alternativen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Personio Payroll', 'personio-payroll', 'Vorbereitende Lohnabrechnung direkt aus dem HR-System', 'Lohnrelevante Daten aus Personio sammeln und per DATEV-Schnittstelle an Kanzlei oder Lohnbüro übergeben.', '<p>Personio Payroll bündelt alle lohnrelevanten Daten wie Stammdaten, Abwesenheiten, Zuschläge und Änderungen direkt im HR-System. Die eigentliche Abrechnung übernimmt anschließend die Kanzlei, die die Daten über die DATEV-Schnittstelle erhält.</p><p>Das reduziert Rückfragen und doppelte Datenerfassung erheblich, ersetzt aber keine vollständige Lohnsoftware.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), 5, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, 'zusätzlich zur HR-Lizenz', '["Mitarbeiterportal","DATEV-Schnittstelle","bAV & Entgeltumwandlung"]'::jsonb, '["Vorbereitende Lohnabrechnung","DATEV-Übergabe an die Kanzlei","Eine Datenbasis mit HR"]'::jsonb, '["DATEV Lohn und Gehalt","DATEV LODAS","Personio"]'::jsonb, '["Keine doppelte Datenerfassung","Weniger Rückfragen der Kanzlei"]'::jsonb, '["Keine eigenständige Lohnabrechnung","Nur mit Personio sinnvoll"]'::jsonb, 'Personio-Kunden, deren Lohn die Kanzlei abrechnet.', null, null, 'export', '[]'::jsonb, null, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.personio.de/produkt/payroll/', 'keins', 'Personio SE & Co. KG', 2015, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 4.3, 3.9, 4, 4, 'Personio Payroll ergänzt die HR-Plattform Personio um die Lohnabrechnung. Sinnvoll ist das vor allem für Unternehmen, die Personio ohnehin nutzen und den Datenfluss zur Abrechnung vereinfachen wollen.', '<h3>Wie es funktioniert</h3><p>Stammdaten, Abwesenheiten, Zuschläge und Änderungen werden in Personio gepflegt und stehen der Abrechnung direkt zur Verfügung. Das beseitigt die klassische Fehlerquelle, bei der HR und Lohnbüro mit unterschiedlichen Datenständen arbeiten.</p><h3>Kosten</h3><p>Personio nennt für die Lohnabrechnung einen Einstiegspreis ab 5 € je Mitarbeitendem im Monat, zusätzlich zur HR-Lizenz. Für Organisationen bis 49 Beschäftigte gibt es HR und Payroll gemeinsam ab 14 € je Mitarbeitendem. Eine Testversion zum Selbstanmelden gibt es nicht, dafür eine interaktive Produkttour und eine persönliche Demo.</p><h3>Fazit</h3><p>Für Personio-Kunden ist Payroll ein logischer Schritt. Wer nur eine Lohnabrechnung sucht, fährt mit einem eigenständigen Programm oder der Kanzlei günstiger.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Paychex Deutschland', 'paychex-deutschland', 'Lohnabrechnung als Outsourcing-Dienstleistung', 'Lohnabrechnung im Outsourcing-Modell. Paychex übernimmt Abrechnung und Meldewesen.', '<p>Paychex Deutschland bietet die Lohnabrechnung als Dienstleistung an: Unternehmen liefern die Bewegungsdaten, Paychex erstellt Abrechnungen, Meldungen und Bescheinigungen.</p><p>Das Modell eignet sich für Unternehmen, die keine eigene Lohnkompetenz aufbauen und nicht über die Steuerkanzlei abrechnen möchten.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), null, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, null, '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","Mitarbeiterportal"]'::jsonb, '["Komplettes Outsourcing","Persönliche Ansprechpartner"]'::jsonb, '["DATEV"]'::jsonb, '["Kein eigenes Lohn-Know-how nötig","Feste Ansprechpartner"]'::jsonb, '["Weniger Kontrolle über den Prozess","Preis nur auf Anfrage"]'::jsonb, 'Unternehmen, die die Lohnabrechnung vollständig auslagern möchten.', null, null, null, '[]'::jsonb, true, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.paychex.de', 'keins', 'Paychex Deutschland GmbH', null, 'Mannheim', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 3.9, 4, 3.7, 4.1, 4, 'Paychex übernimmt die Lohnabrechnung vollständig als Dienstleistung. Das entlastet Betriebe ohne eigene Lohnexpertise, macht sie aber auch abhängig vom Dienstleister.', '<h3>Das Modell</h3><p>Paychex ist kein Programm, das Sie selbst bedienen, sondern ein Outsourcing-Anbieter. Sie melden Stunden, Eintritte, Austritte und Änderungen, Paychex rechnet ab, übermittelt die Meldungen und stellt die Unterlagen bereit.</p><h3>Für wen es passt</h3><p>Das Modell eignet sich für Unternehmen ohne Steuerkanzlei, die die Lohnabrechnung übernimmt, und ohne eigene Lohnbuchhaltung. Wer bereits eine Kanzlei hat, bekommt dort meist eine vergleichbare Leistung.</p><h3>Kosten</h3><p>Preise gibt es auf Anfrage, sie richten sich nach Mitarbeiterzahl und Leistungsumfang. Vergleichen Sie das Angebot mit dem Lohnhonorar Ihrer Kanzlei und mit Selbstabrechnungslösungen wie Sage HR & Payroll.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Personio', 'personio', 'Das HR-Betriebssystem für den Mittelstand', 'All-in-one-HR-Software für Personalakte, Abwesenheiten, Recruiting, Onboarding und vorbereitende Lohnabrechnung.', '<p>Personio ist die im deutschsprachigen Mittelstand am weitesten verbreitete HR-Software. Sie bündelt digitale Personalakte, Abwesenheits- und Zeitmanagement, Recruiting, Onboarding und Performance-Management in einer Plattform für Unternehmen von etwa 10 bis 2.000 Mitarbeitenden.</p><p>Lohnrelevante Daten werden über die DATEV-Schnittstelle an Kanzlei oder Lohnbüro übergeben. Das Rollen- und Rechtekonzept erlaubt eine saubere Abstimmung mit dem Betriebsrat nach § 87 BetrVG.</p>', null, (select id from public.categories where slug = 'hr-software'), 7.6, 'EUR', 'month', true, 'employee', false, null, false, true, '[{"name":"Core","price":null,"period":"month","unit":"employee","description":"Preis auf Anfrage","features":["Personalakte","Abwesenheiten","Zeiterfassung","Reporting"]},{"name":"Professional","price":null,"period":"month","unit":"employee","description":"Preis auf Anfrage","features":["Alles aus Core","Recruiting","Onboarding","Vorbereitende Lohnabrechnung"],"highlighted":true},{"name":"Enterprise","price":null,"period":"month","unit":"employee","description":"Preis auf Anfrage","features":["Alles aus Professional","Performance & Entwicklung","Erweiterte Workflows","Dedizierter Support"]}]'::jsonb, 'HR ab 50 Mitarbeitenden; bis 49 Mitarbeitende HR mit Payroll ab 14 €', '["Digitale Personalakte","Abwesenheitsmanagement","Recruiting & Bewerbermanagement","Onboarding","Zeiterfassung","Vorbereitende Lohnabrechnung","Performance & Feedback","Rollen & Rechte","Mitarbeiter-App"]'::jsonb, '["DATEV-Schnittstelle für die Lohnvorbereitung","Automatisierte HR-Workflows","Betriebsratstaugliches Rechtekonzept","Über 200 Integrationen"]'::jsonb, '["DATEV","Slack","Microsoft Teams","Google Workspace","clockodo","softgarden","Lexware Office"]'::jsonb, '["Sehr gute Workflows","Große Integrationsvielfalt","Stark im Mittelstand verbreitet"]'::jsonb, '["Konkrete Preise erst nach einer Demo, eher im oberen Segment","Keine Testversion zum Selbststarten","Einrichtung braucht Zeit"]'::jsonb, 'Mittelständler mit 20 bis 1.000 Mitarbeitenden.', null, null, 'export', '[]'::jsonb, null, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.personio.de/', 'direkt', 'Personio SE & Co. KG', 2015, 'München', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch","Französisch","Spanisch","Italienisch","Niederländisch"]'::jsonb, 4.5, 4.5, 4, 4.3, 4.7, 'Personio ist die bekannteste HR-Plattform im deutschen Mittelstand und das aus gutem Grund. Die Software ist ausgereift, gut bedienbar und deckt Personalakte, Abwesenheiten, Recruiting und Performance ab, hat aber auch ihren Preis.', '<h3>Was Personio leistet</h3><p>Die Münchner Plattform verwaltet Personaldaten, Dokumente, Abwesenheiten und Arbeitszeiten und begleitet den Weg von der Bewerbung über das Onboarding bis zum Austritt. Über Apps lassen sich Recruiting, Performance und Entwicklung ergänzen. Mehr als 16.000 Unternehmen nutzen Personio nach Angaben des Anbieters.</p><h3>Stärken</h3><p>Die Bedienung ist für Beschäftigte wie für die Personalabteilung verständlich. Genehmigungsprozesse, etwa für Urlaub oder Dokumente, lassen sich flexibel gestalten. Die vorbereitende Lohnabrechnung überträgt alle relevanten Daten an die Kanzlei oder an Personio Payroll.</p><h3>Preise</h3><p>Für Unternehmen ab 50 Beschäftigten beginnen die HR-Lösungen bei 7,60 € je Mitarbeitendem im Monat. Für Organisationen bis 49 Beschäftigte gibt es HR und Payroll gemeinsam ab 14 €. Die genaue Höhe hängt von Plan und Apps ab, ein Angebot gibt es nach einer Demo. Eine selbst gestartete Testversion bietet Personio nicht an, wohl aber eine interaktive Produkttour.</p><h3>Für wen es passt</h3><p>Für wachsende Unternehmen zwischen 20 und 2.000 Beschäftigten ist Personio eine sichere Wahl. Sehr kleine Betriebe finden bei Factorial oder Sage HR & Payroll günstigere Einstiege.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('HRworks', 'hrworks', 'HR-Software mit integrierter Reisekostenabrechnung', 'HR-Software aus Freiburg mit Personalakte, Zeiterfassung, Abwesenheiten und besonders starker Reisekostenabrechnung.', '<p>HRworks deckt die klassischen HR-Prozesse ab, also Personalakte, Abwesenheiten, Zeiterfassung und Recruiting. Es hebt sich durch eine ausgereifte Reisekostenabrechnung nach den aktuellen BMF-Pauschalen ab.</p><p>Die Software ist besonders für Unternehmen ab etwa 20 Mitarbeitenden interessant und wird in Deutschland gehostet.</p>', null, (select id from public.categories where slug = 'hr-software'), 6, 'EUR', 'month', true, 'employee', true, null, false, true, '[]'::jsonb, 'mindestens 20 Nutzer werden berechnet', '["Digitale Personalakte","Abwesenheitsmanagement","Recruiting & Bewerbermanagement","Onboarding","Zeiterfassung","Vorbereitende Lohnabrechnung","Reisekosten","Rollen & Rechte","Mitarbeiter-App"]'::jsonb, '["Reisekosten nach BMF-Pauschalen","Zeiterfassung integriert","Hosting in Deutschland"]'::jsonb, '["DATEV","Microsoft Teams","Outlook"]'::jsonb, '["Reisekosten sehr gut gelöst","Faire Preisgestaltung","Deutscher Support"]'::jsonb, '["Oberfläche weniger modern","Weniger Integrationen als Personio"]'::jsonb, 'Unternehmen ab 20 Mitarbeitenden mit vielen Dienstreisen.', null, null, 'export', '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.hrworks.de', 'keins', 'HRworks GmbH', null, 'Freiburg im Breisgau', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.2, 4.2, 4.4, 4.4, 'HRworks aus Freiburg ist eine ausgereifte HR-Software mit einer besonders starken Reisekostenabrechnung. Für Mittelständler mit Außendienst ist das oft der entscheidende Vorteil.', '<h3>Was HRworks auszeichnet</h3><p>Personalakte, Abwesenheiten, Zeiterfassung und Recruiting gehören zum Standard. Heraus sticht die Reisekostenabrechnung, die nach den aktuellen Pauschalen des Bundesfinanzministeriums rechnet und Belege per App erfasst. Wer viele Dienstreisen abrechnet, spart hier mehr Zeit als bei jedem anderen HR-Modul.</p><h3>Im Alltag</h3><p>Die Oberfläche ist sachlich und klar, der Support deutschsprachig und gut erreichbar. Daten für die Lohnabrechnung gehen im DATEV-Format an die Kanzlei.</p><h3>Kosten</h3><p>HRworks rechnet pro Nutzer ab, mindestens 20 Nutzer werden berechnet. In den ersten sechs Monaten gilt die zu Beginn bestellte Lizenzzahl als Untergrenze. Für ein genaues Angebot und eine Demo bietet HRworks eine Beratung an.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage HR Suite', 'sage-hr-suite', 'Modularer HR-Baukasten', 'Modulare HR-Lösung, bei der Unternehmen nur die benötigten Bausteine lizenzieren.', '<p>Die Sage HR Suite ist als Baukasten aufgebaut: Personalakte, Abwesenheiten, Zeiterfassung, Bewerbermanagement und weitere Module lassen sich einzeln hinzubuchen.</p><p>In Kombination mit der Sage-Lohnabrechnung entsteht eine durchgängige Lösung von der Stammdatenpflege bis zur Abrechnung.</p>', null, (select id from public.categories where slug = 'hr-software'), 39, 'EUR', 'month', true, 'employee', false, null, false, true, '[{"name":"Personalabrechnung","price":39,"period":"month","unit":"account","features":["Stammdatenverwaltung","Einzel- und Massenabrechnung, Rückrechnung","Bescheinigungen und Auswertungen"],"highlighted":true},{"name":"Zeitmanagement","price":21,"period":"month","unit":"account","features":["Zeiterfassung ortsunabhängig","Zeitbewertung über die Personalabrechnung"]},{"name":"Bewerbermanagement","price":19,"period":"month","unit":"account","features":["Stellenausschreibung","Jobportale ab Professional"]}]'::jsonb, 'je Modul, Lizenz in 25er Mitarbeiterpaketen, jährliche Zahlung', '["Digitale Personalakte","Abwesenheitsmanagement","Recruiting & Bewerbermanagement","Zeiterfassung","Vorbereitende Lohnabrechnung","Rollen & Rechte","Mitarbeiter-App"]'::jsonb, '["Module einzeln buchbar","Integration mit Sage-Lohn"]'::jsonb, '["Sage Lohnabrechnung","Sage Active","DATEV"]'::jsonb, '["Günstiger Einstieg","Flexibel erweiterbar"]'::jsonb, '["Kosten summieren sich mit Modulen","Weniger intuitiv als Neueinsteiger"]'::jsonb, 'KMU, die HR schrittweise digitalisieren.', null, null, 'export', '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-hr-suite-personal-software/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 3.8, 4.1, 4.3, 4.7, 'Die Sage HR Suite ist eine modulare Personal- und Abrechnungssoftware für den gehobenen Mittelstand. Sie lässt sich lokal oder in der Cloud betreiben und Schritt für Schritt ausbauen.', '<h3>Einordnung</h3><p>Während Sage HR & Payroll auf kleinere Betriebe zielt, ist die HR Suite für mittlere und große Unternehmen gebaut. Personalabrechnung, Personalmanagement, Bewerbermanagement, Zeitwirtschaft und Reisekosten sind eigene Module, die sich einzeln lizenzieren lassen.</p><h3>Stärken</h3><p>Die Personalabrechnung beherrscht Einzel- und Massenabrechnung, Rückrechnungen und umfangreiche Auswertungen. Die Zeitwirtschaft erfasst Arbeitszeiten ortsunabhängig und bewertet sie direkt für die Abrechnung. Wer Wert auf den Betrieb im eigenen Rechenzentrum legt, hat diese Wahl, was bei Cloud-Anbietern selten ist.</p><h3>Preise</h3><p>Die Personalabrechnung beginnt bei 39 € im Monat, das Zeitmanagement bei 21 € und das Bewerbermanagement bei 19 €. Lizenziert wird in Paketen zu je 25 Mitarbeitenden, bei jährlicher Rechnung und zwölf Monaten Mindestlaufzeit. Sage bietet eine Produkttour und ein Infopaket, ein Angebot gibt es auf Anfrage.</p><h3>Fazit</h3><p>Für Unternehmen mit mehreren hundert Beschäftigten und dem Wunsch nach einer integrierten Lösung aus Abrechnung und HR ist die Suite eine starke, in Deutschland verwurzelte Option.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('rexx systems', 'rexx-systems', 'Talent- und HR-Management für den oberen Mittelstand', 'Umfassende HR- und Recruiting-Suite für den oberen Mittelstand und Konzerne.', '<p>rexx systems bietet eine sehr breite HR-Suite von Recruiting über Talent-Management bis zur Personalentwicklung. Die Lösung ist hoch konfigurierbar und richtet sich an größere Organisationen mit komplexen Prozessen.</p><p>Die Lizenzierung erfolgt modulweise; Preise werden individuell kalkuliert.</p>', null, (select id from public.categories where slug = 'hr-software'), null, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, null, '["Digitale Personalakte","Abwesenheitsmanagement","Recruiting & Bewerbermanagement","Onboarding","Zeiterfassung","Performance & Feedback","Zeugnisgenerator","Reisekosten","Rollen & Rechte"]'::jsonb, '["Sehr starkes Recruiting","Hohe Konfigurierbarkeit","Zeugnisgenerator"]'::jsonb, '["DATEV","SAP","LinkedIn","StepStone"]'::jsonb, '["Enormer Funktionsumfang","Für komplexe Organisationen geeignet"]'::jsonb, '["Einführungsprojekt nötig","Für kleine Firmen überdimensioniert"]'::jsonb, 'Oberer Mittelstand und Konzerne.', null, null, 'export', '[]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.rexx-systems.com', 'keins', 'rexx systems GmbH', null, 'Hamburg', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 3.7, 3.9, 4.1, 4.7, 'rexx systems ist eine umfassende HR-Suite aus Hamburg mit besonders starkem Recruiting. Die Stärke liegt in der Tiefe, der Preis dafür ist ein höherer Einführungsaufwand.', '<h3>Was rexx leistet</h3><p>Von der Stellenausschreibung über das Bewerbermanagement bis zur Personalentwicklung deckt rexx den gesamten Mitarbeiterlebenszyklus ab. Viele Unternehmen setzen die Software vor allem wegen des Bewerbermanagements ein, das auch große Mengen an Bewerbungen strukturiert.</p><h3>Einführung</h3><p>Die Suite ist sehr konfigurierbar. Das ist für größere Organisationen ein Vorteil, bedeutet aber auch, dass die Einführung als Projekt geplant werden sollte. Für kleine Betriebe ist rexx meist zu umfangreich.</p><h3>Kosten</h3><p>Preise veröffentlicht rexx nicht, sie richten sich nach Modulen und Mitarbeiterzahl. Eine Demo ist kostenlos.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Factorial', 'factorial', 'HR-Software für kleine und mittlere Unternehmen', 'Übersichtliche HR-Software mit Zeiterfassung, Abwesenheiten, Personalakte und Recruiting.', '<p>Factorial richtet sich an kleine und mittlere Unternehmen, die ihre HR-Prozesse schnell digitalisieren möchten. Zeiterfassung, Abwesenheiten, Personalakte und Recruiting sind in einer modernen Oberfläche vereint.</p><p>Für Deutschland stehen eine deutschsprachige Oberfläche und ein Export für die Lohnabrechnung zur Verfügung.</p>', null, (select id from public.categories where slug = 'hr-software'), 8, 'EUR', 'month', true, 'user', true, null, false, true, '[]'::jsonb, null, '["Digitale Personalakte","Abwesenheitsmanagement","Recruiting & Bewerbermanagement","Onboarding","Zeiterfassung","Performance & Feedback","Mitarbeiter-App"]'::jsonb, '["Schnelle Einrichtung","Moderne App","Zeiterfassung inklusive"]'::jsonb, '["DATEV","Slack","Google Workspace"]'::jsonb, '["Intuitive Bedienung","Schnell startklar"]'::jsonb, '["Lohnexport weniger tief als bei deutschen Anbietern","Support teils englischsprachig"]'::jsonb, 'Kleine Unternehmen mit 10 bis 200 Mitarbeitenden.', null, null, 'export', '[]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Spanien', '2026-09-22', null, 'https://factorialhr.de/', 'keins', 'Factorial HR', 2016, 'Barcelona', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4.5, 4.2, 3.9, 4.1, 'Factorial ist eine leicht zugängliche HR-Software für kleine und mittlere Unternehmen mit einem günstigen Einstieg ab 8 € je Nutzer. Sie deckt die wichtigsten HR-Prozesse ab, ohne mit Funktionen zu überfordern.', '<h3>Worum es geht</h3><p>Die Plattform aus Barcelona verwaltet Personaldaten, Abwesenheiten, Arbeitszeiten, Dokumente und Schichten. Beschäftigte stempeln per App, beantragen Urlaub und finden ihre Unterlagen an einer Stelle.</p><h3>Stärken</h3><p>Die Einrichtung geht schnell, die Oberfläche ist modern und auch für Mitarbeitende ohne Schulung verständlich. Für Betriebe, die von Excel-Listen und Papieranträgen kommen, ist der Umstieg einfach.</p><h3>Kosten</h3><p>Factorial nennt einen Einstieg ab 8 € pro Nutzer im Monat und erstellt darüber hinaus individuelle Angebote. Eine kostenlose Testphase und eine Demo werden angeboten.</p><h3>Fazit</h3><p>Für kleine und mittlere Betriebe ohne komplexe Anforderungen ist Factorial ein guter, bezahlbarer Einstieg. Wer tiefere Mitbestimmungs- oder Reportinganforderungen hat, sollte Personio und HRworks daneben prüfen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
